window.CARBOON_METHODOLOGY_KB = [
    { id:"carboon-overview", topic:"CARBOON overview", keywords:["carboon", "what is carboon", "carboon calculator", "whole-life carbon calculator", "about carboon", "web-based tool", "carbon platform", "carbon dashboard", "tool", "platform", "project", "calculator"], answer:"CARBOON is a web-based Whole-Life Carbon Calculator for buildings, compliant with EN 15978. It accepts building geometry and type parameters, estimates material quantities from a parametric Bill of Quantities model, and calculates embodied, operational, end-of-life and circular-economy carbon across all lifecycle stages (A-D), presented through 13 visualisation sections.", links:[{href:"#what",label:"What is CARBOON?"}, {href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"standards", topic:"Standards & frameworks", keywords:["en 15978", "15978", "en 15804", "15804", "standards", "standard", "compliant", "framework", "rics", "cibse", "bsria", "ipcc", "reference standard", "calculation method"], answer:"CARBOON is built on EN 15978:2011 (building environmental performance) and EN 15804 (EPD core rules), plus RICS Whole Life Carbon Assessment (2023), LEED v5, CIBSE Guide F, BSRIA, the UK Woodland Carbon Code, the ICE database, and IPCC AR5 (refrigerant GWP). Results are reported across the full EN 15978 module structure A-D.", links:[{href:"#references",label:"References & sources"}, {href:"#what",label:"What is CARBOON?"}] },
    { id:"lifecycle-stages", topic:"Lifecycle stages A-D", keywords:["lifecycle stages", "life cycle stages", "modules", "a-d", "module", "what are the stages", "stages a", "stages a-d", "en 15978 stages", "a1", "c4"], answer:"CARBOON covers EN 15978 lifecycle modules A1-A5 (product & construction), B1-B7 (in-use), C1-C4 (end-of-life) and D (beyond system boundary: reuse, recycling, energy recovery). Each stage is shown separately so you can see where carbon is concentrated.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"a1a3", topic:"Module A1-A3 (product stage / embodied carbon)", keywords:["a1-a3", "a1 a3", "a1a3", "product stage", "cradle to gate", "embodied carbon", "material extraction", "manufacturing", "boq", "bill of quantities", "material carbon", "upfront carbon", "materials"], answer:"Modules A1-A3 cover cradle-to-gate embodied carbon: raw material extraction (A1), transport to manufacturer (A2) and manufacturing (A3). If you provide a Bill of Quantities (BoQ) in the input JSON, A1-A3 is computed directly from material quantities x ICE factors; otherwise a parametric model estimates it from area, floors, structure type, envelope, grid spacing and window-to-wall ratio.", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#download",label:"Download & setup"}] },
    { id:"a4", topic:"Module A4 (transport to site)", keywords:["a4", "transport to site", "transport", "delivery", "freight", "road freight", "haulage"], answer:"Module A4 is transport of materials to site. Local materials (concrete, aggregates, bricks, blocks) use a default 50 km haul; manufactured materials (steel, glass, insulation, timber) use 300 km. The emission factor is 0.12 kgCO2e/t.km (DEFRA 2023).", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"a5", topic:"Module A5 (construction / installation)", keywords:["a5", "construction", "installation", "on-site", "site works", "temporary works", "waste processing", "site energy"], answer:"Module A5 covers on-site construction. It is estimated at 6.5% of A1-A3 embodied carbon for site energy, waste processing and temporary works, following BS EN 15978 default scenarios and RICS WLCA guidance.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"b1", topic:"Module B1 (refrigerant leakage)", keywords:["b1", "refrigerant", "refrigerant leakage", "hvac", "leakage", "gwp", "fugitive", "air conditioning"], answer:"Module B1 covers fugitive refrigerant emissions from HVAC leakage. If actual refrigerant data is provided it is used directly; otherwise defaults are 2%/year for split systems and 5%/year for VRF, with GWP values from IPCC AR5 (e.g. R-410A = 2088 kgCO2e/kg).", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"b2b5", topic:"Modules B2-B5 (refurbishment / repair / replacement)", keywords:["b2", "b3", "b4", "b5", "b2-b5", "refurbishment", "repair", "replacement", "maintenance", "in-use", "estimated"], answer:"Modules B2-B5 cover maintenance, repair, replacement and refurbishment over the building's life. Provided data is used directly; if missing, CARBOON marks them 'Estimated' and assumes no extra in-use embodied carbon beyond the upfront A1-A5 values. In the current sample dataset, B5 refurbishment has actual data while B2-B4 are zero.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"b6", topic:"Module B6 (operational energy)", keywords:["b6", "operational energy", "energy", "eui", "energy use intensity", "heating", "cooling", "lighting", "grid", "electricity", "fossil fuel", "kwh", "energyplus"], answer:"Module B6 is operational energy carbon: B6 = EUI (kWh/m2/yr) x GFA x Grid EF / 1000 x lifetime (years). Default EUIs: Large Office 311, Hospital 450, Apartment 180, Primary School 200, Warehouse 130 (BSRIA/CIBSE). Grid factors cover 20 countries x 4 decarbonisation scenarios (Conservative/Moderate/Ambitious/Net Zero) with interpolation between 2020-2050.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"b7", topic:"Module B7 (operational water)", keywords:["b7", "operational water", "water", "water supply", "water treatment", "water intensity", "water carbon"], answer:"Module B7 is carbon from water supply and treatment, estimated from CIBSE Guide G / BSRIA benchmarks (e.g. Large Office 0.65 m3/m2/yr) at 0.35 kgCO2e/m3. If not provided in the JSON, B7 is marked 'Estimated'.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"c1c4", topic:"Modules C1-C4 (end of life)", keywords:["c1", "c2", "c3", "c4", "c1-c4", "end of life", "demolition", "deconstruction", "waste processing", "disposal", "landfill"], answer:"Modules C1-C4 are end-of-life: C1 demolition approx 4.5 kgCO2e/m2 GFA; C2 transport 50 km at 0.12 kgCO2e/t.km; C3 material processing (concrete crushing 4.5, steel sorting 2.5, timber chipping 12 kgCO2e/t); C4 disposal (timber 0.58 kgCO2e/kg from anaerobic decomposition; plastics/insulation 0.02-0.05; inert materials negligible). Provided C-breakdown data is shown as 'Actual'.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"module-d", topic:"Module D (beyond system boundary / circular economy)", keywords:["module d", "beyond system boundary", "circular economy", "recycling", "reuse", "recovery", "avoided burden", "d credits", "circular"], answer:"Module D captures net benefits beyond the system boundary from reuse, recycling and energy recovery: D = sum of mass x recycling_rate x (-avoided_burden). Recycling rates come from the ICE database (steel rebar 95%, concrete 75% downcycled, timber 40% energy recovery). D values are typically negative - a carbon credit.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"leed-v5", topic:"LEED v5 integration", keywords:["leed v5", "leed 5", "leed five", "leed", "leed credits", "leed credit", "certification", "usgbc", "bd+c", "leed v5 integration"], answer:"CARBOON supports LEED v5 BD+C by mapping its metrics to Materials & Resources (MR) and Energy & Atmosphere (EA) credits. MRc2 (embodied carbon) is calculated directly; EAc3 (energy) is shown as passive-design POTENTIAL only; MRp2 (waste management) is supported. See the LEED tab (Section N) for the live assessment.", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#references",label:"References & sources"}] },
    { id:"mrc2", topic:"MRc2 - Reduce Embodied Carbon", keywords:["mrc2", "reduce embodied carbon", "embodied carbon credit", "mrc2 points", "embodied carbon reduction", "structure enclosure", "structure and enclosure"], answer:"MRc2 (Reduce Embodied Carbon of Structure & Enclosure, 2-6 points) compares your project's A1-A5 embodied carbon per m2 GFA against a baseline (default 1,050 kgCO2e/m2 for RC-frame commercial; user-adjustable). CARBOON CALCULATES this credit directly and shows a live point score in Section N.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"mrc2-thresholds", topic:"MRc2 point thresholds", keywords:["mrc2 thresholds", "point thresholds", "reduction percentage", "how many points", "10% 3 pts", "20% 4 pts", "30% 5 pts", "40% 6 pts", "reduction %"], answer:"MRc2 point thresholds: 0% = 2 pts (baseline/WBLCA), 10% = 3 pts, 20% = 4 pts, 30% = 5 pts, 40%+ = 6 pts (exemplary). Reduction % = (Baseline - Project) / Baseline x 100. Platinum needs >= 20% (4+ pts).", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"eac3", topic:"EAc3 - Passive Design Potential", keywords:["eac3", "calculate eac3", "eac3 points", "eac3 credits", "does carboon calculate eac3", "passive design", "energy efficiency credit", "passive", "potential", "energyplus", "ashrae", "not calculated", "energy credit"], answer:"EAc3 (Energy & Atmosphere, up to 18 points) rewards energy performance vs ASHRAE 90.1-2019. CARBOON does NOT run energy simulation, so EAc3 is shown as POTENTIAL only - derived from passive-design metrics (WWR, OTTV proxy, facade surface-to-volume). Confirmed EAc3 points require EnergyPlus modelling, which CARBOON does not perform.", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#references",label:"References & sources"}] },
    { id:"mrp2", topic:"MRp2 - Construction & Demolition Waste", keywords:["mrp2", "waste management", "construction and demolition", "cd waste", "diversion", "prerequisite", "waste plan"], answer:"MRp2 is a prerequisite (required, 0 points) for a construction & demolition waste management plan. CARBOON supports it by tracking end-of-life waste streams (C3-C4) by material, providing ICE recycling rates, and showing Module D recovery benefits you can cite in the plan.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"platinum", topic:"LEED v5 Platinum requirements", keywords:["platinum", "leed platinum", "platinum requirements", "platinum ready", "renewable energy", "fossil-fuel-free", "fossil free", "100% renewable"], answer:"For LEED v5 Platinum, CARBOON's live readiness check verifies three carbon criteria: (1) embodied carbon reduction >= 20% vs baseline, (2) 100% renewable energy (on-site, PPA or RECs), (3) fossil-fuel-free (no on-site combustion). It shows 'Platinum Ready: Yes/No' with gap analysis. Other LEED categories are outside CARBOON's scope.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"leed-export", topic:"LEED export & documentation", keywords:["leed export", "export leed", "export pdf", "documentation", "submission", "export full report", "leed summary"], answer:"The LEED tab (Section N) has 'Export LEED Summary' (a formatted PDF for LEED submission: metrics, MRc2 calculated points, EAc3 potential, carbon hotspot top-3 elements, platinum status, 25-year projection) and 'Export Full Report' (full dashboard PDF for supplementary documentation).", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"ice-database", topic:"ICE materials database", keywords:["ice database", "ice", "embodied carbon factors", "material factors", "university of bath", "datasets", "data sources", "materials database", "carbon factors"], answer:"CARBOON embeds the ICE (Inventory of Carbon & Energy) v3.0 database (University of Bath, 2019) with factors for 40+ construction materials - each with embodied carbon, density, recycling rate, landfill factor, and (for timber) biogenic storage. It is the primary source for A1-A3 factors.", links:[{href:"#references",label:"References & sources"}, {href:"#download",label:"Download & setup"}] },
    { id:"grid-factors", topic:"Grid emission factors", keywords:["grid emission factors", "grid ef", "grid carbon", "decarbonisation scenarios", "net zero scenario", "country grid", "20 countries", "clp", "hk electric", "grid intensity"], answer:"CARBOON embeds grid carbon intensity for 20 countries/regions across 4 scenarios - Conservative, Moderate, Ambitious, Net Zero - with data points for 2020, 2030, 2040, 2050 and linear interpolation. Sources: IEA World Energy Outlook and national grid operators. (HK: CLP 0.50, HK Electric 0.59 kgCO2e/kWh.)", links:[{href:"#references",label:"References & sources"}] },
    { id:"biogenic", topic:"Biogenic carbon (timber)", keywords:["biogenic carbon", "timber carbon", "carbon storage", "clt", "glulam", "wood", "sequestration", "negative carbon", "biogenic"], answer:"Timber/wood products store biogenic carbon, treated as an instantaneous credit at year 0 (EN 15804). Embedded factors: CLT -0.85, glulam -0.80, timber framing -1.00, plywood -0.78, wood-fibre insulation -0.65 kgCO2e/kg (negative = net sequestration). It is released at end-of-life (C4).", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#references",label:"References & sources"}] },
    { id:"badges", topic:"Estimated vs Actual badges", keywords:["actual", "estimated", "partial", "data badge", "data source", "transparency", "green badge", "orange badge", "purple badge", "badge meaning"], answer:"Every dashboard section shows a data-source badge: green 'Actual' (direct from your JSON), purple 'Partial' (mix of actual + estimated), orange 'Estimated' (fully computed by the engine from benchmarks/extrapolation). This keeps the calculation transparent and auditable.", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#references",label:"References & sources"}] },
    { id:"lifetime-slider", topic:"Variable building lifetime", keywords:["lifetime", "building lifetime", "service life", "slider", "extrapolation", "years", "20-120", "variable lifetime", "lifetime slider"], answer:"The lifetime slider (20-120 years) explores how service life affects whole-life carbon. Lifetime-INDEPENDENT parts (A1-A5, C1-C4, D) stay fixed; lifetime-DEPENDENT parts (B6 energy, B7 water, B1, B2-B5) scale linearly with years. If the JSON lacks annual fields, the engine derives them by dividing total by lifetime.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"grid-decarbonisation", topic:"Grid decarbonisation / time series", keywords:["grid decarbonisation", "decarbonisation trajectory", "time series", "2% per year", "25-year projection", "section k", "future grid", "decarbonised"], answer:"Section K (time-series) applies a 2%/year linear reduction to annual operational carbon to model grid decarbonisation, creating the dashed 'decarbonised' projection. The rate floors at 20% of the starting value from year 40 onward.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"carbon-offset", topic:"Carbon offset methodology (Section L)", keywords:["carbon offset", "offset", "woodland", "tree planting", "sequestration rate", "hk$250", "offset cost", "section l", "offsets"], answer:"Section L offsets whole-life carbon via woodland sequestration at 4.5 tCO2e/ha/yr (UK Woodland Carbon Code; conservative for tropical regions). Cost: HK$250/tCO2e (woodland) and HK$950/tCO2e (estate retrofit); ~1 GBP = 10 HKD. Contextual equivalents (football fields, Victoria Park) make land area relatable for Hong Kong users.", links:[{href:"#dashboard",label:"Open the Dashboard"}] },
    { id:"grasshopper", topic:"Grasshopper integration", keywords:["grasshopper", "rhino", "integration", "parametric", "export script", "json fields", "annualised", "plugin", "gha", "carbon engine"], answer:"CARBOON is a Grasshopper definition (not a compiled .gha plugin). Its carbon logic lives in Python script components; the core ships as carbon_engine.py, pasted into the file-transfer component. For best lifetime-slider behaviour, add annualised fields (_annualOC_kg, _annualB6_kg, _fixedEC_kg, etc.) to the Grasshopper export so the dashboard scales operational carbon precisely.", links:[{href:"#download",label:"Download & setup"}, {href:"#references",label:"References & sources"}] },
    { id:"installation", topic:"Installation & requirements", keywords:["install", "installation", "setup", "rhino", "ladybug", "wallacei install", "requirements", "how to install", "run carboon"], answer:"To run CARBOON: install Rhino 7/8 + Grasshopper, plus the third-party plugins Ladybug (climate/sun data) and Wallacei (NSGA-II optimisation). Download the package, open the .gh definition, and paste carbon_engine_v2.0.py into the file-transfer component. Honeybee, Dragonfly and EnergyPlus are NOT used.", links:[{href:"#download",label:"Download & setup"}] },
    { id:"limitations", topic:"Limitations & caveats", keywords:["limitations", "caveats", "what it doesn't do", "not do", "accuracy", "parametric accuracy", "+/-30%", "regional", "scope 1 2 3", "monte carlo", "dynamic thermal"], answer:"Key caveats: parametric BoQ is +/-30% accurate (not a detailed BoQ); ICE factors are UK/European (may differ regionally); biogenic carbon is treated at year 0; B7 uses UK water benchmarks (not HK desalination). CARBOON does NOT do dynamic thermal simulation, climate-change impacts, Monte Carlo, or Scope 1/2/3 splitting - and EAc3 is potential only.", links:[{href:"#references",label:"References & sources"}, {href:"#what",label:"What is CARBOON?"}] },
    { id:"ottv-hk", topic:"OTTV in Hong Kong", keywords:["ottv", "hong kong ottv", "otttv cap", "envelope efficiency", "bd app-67", "20 w/m2", "overall thermal transfer value"], answer:"OTTV (Overall Thermal Transfer Value) measures envelope heat gain. Hong Kong's commercial-tower cap is <= 20 W/m2 (BD APP-67). CARBOON uses a simple OTTV proxy from passive-design metrics to indicate envelope efficiency and EAc3 readiness.", links:[{href:"#dashboard",label:"Open the Dashboard"}, {href:"#references",label:"References & sources"}] },
    { id:"glossary", topic:"Glossary", keywords:["glossary", "what does x mean", "definition", "abbreviation", "eui", "wwr", "ottv", "gfa", "ec", "oc", "wlc", "boq", "clt", "gwp", "mean"], answer:"Quick glossary: EC = embodied carbon (A1-A5 + B2-B5); OC = operational carbon (B1, B6-B7); WLC = whole-life carbon (EC + OC + EOL + D); EUI = energy use intensity (kWh/m2/yr); WWR = window-to-wall ratio; OTTV = overall thermal transfer value; GFA = gross floor area; BoQ = bill of quantities; CLT = cross-laminated timber; GWP = global warming potential; ICE = Inventory of Carbon & Energy; tCO2e = tonnes CO2-equivalent.", links:[{href:"#references",label:"References & sources"}, {href:"#what",label:"What is CARBOON?"}] },
    { id:"about-project", topic:"About the CARBOON project", keywords:["who made carboon", "team", "aedas", "hku", "cuhk", "internship", "research", "collaborators", "about carboon project"], answer:"CARBOON was built in the Aedas Research Internship Programme 2026 - a collaboration between Aedas, HKU and CUHK - by five Master of Architecture research interns exploring how AI can optimise building form/facade for lower-carbon design. It is an early-stage research tool; the LEED v5 assessment is indicative 'Potential' (MRc2 calculated, EAc3 potential).", links:[{href:"#about",label:"About the project"}, {href:"#references",label:"References & sources"}] },
    { id:"references", topic:"References & further reading", keywords:["references", "further reading", "sources", "usgbc", "rics", "leti", "riba", "cibse", "istructe", "hkgbc"], answer:"CARBOON's factors and benchmarks draw on LEED v5 BD+C, HK Buildings Energy Efficiency Ordinance (Cap. 610), OTTV Code of Practice, HKGBC guidebook, CWCT, IStructE, ICE database, CLP/HK Electric, WSP, RIBA 2030, LETI, RICS WLCA (2023), EN 15978/15804. See the References page for the full list and links.", links:[{href:"#references",label:"References & sources"}] },
    { id:"methodology-guidebook", topic:"Methodology Guidebook", keywords:["methodology guidebook", "guidebook", "methodology", "v2.0", "documentation pdf", "how is it calculated", "methodology pdf"], answer:"The CARBOON Methodology Guidebook v2.0 (July 2026) documents all estimation methods, data sources, standards, assumptions, LEED v5 mapping and limitations across dashboard sections A-N. It is EN 15978-compliant and LEED v5-ready. The full PDF is available in the project folder.", links:[{href:"CARBOON_Methodology_Guidebook_v2.0.pdf",label:"Methodology Guidebook (PDF)"}, {href:"#references",label:"References & sources"}] }
];
